import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename

app = Flask(__name__)

UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
CONVERT_BIN = os.environ.get('CONVERT_BIN', '/usr/local/bin/convert_doc')
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_options(options_str):
    """Remove obviously dangerous shell metacharacters from options."""
    # Strip common injection chars but allow hyphens for flags
    blocked = ['&&', '||', '>', '<', '`']
    result = options_str
    for b in blocked:
        result = result.replace(b, '')
    return result

@app.route('/api/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    # Check file size
    file.seek(0, 2)
    size = file.tell()
    file.seek(0)
    if size > MAX_FILE_SIZE:
        return jsonify({'error': 'File too large'}), 400

    filename = secure_filename(file.filename)
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    input_path = os.path.join(UPLOAD_DIR, filename)
    file.save(input_path)

    # Get conversion format and options from request
    output_format = request.form.get('format', 'pdf')
    extra_options = request.form.get('options', '')

    # Validate output format
    valid_formats = ['pdf', 'html', 'epub', 'markdown']
    if output_format not in valid_formats:
        return jsonify({'error': 'Invalid output format'}), 400

    # Sanitize user-provided options
    clean_options = sanitize_options(extra_options)

    output_filename = filename.rsplit('.', 1)[0] + '.' + output_format
    output_path = os.path.join(UPLOAD_DIR, output_filename)

    # Build conversion command
    cmd = f"{CONVERT_BIN} --input {input_path} --output {output_path} --format {output_format} {clean_options}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )
        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'details': result.stderr.decode()[:200]}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

    if not os.path.exists(output_path):
        return jsonify({'error': 'Output file not generated'}), 500

    return send_file(output_path, as_attachment=True, download_name=output_filename)

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

@app.route('/api/formats', methods=['GET'])
def list_formats():
    return jsonify({'input': list(ALLOWED_EXTENSIONS), 'output': ['pdf', 'html', 'epub', 'markdown']})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
